<script setup lang="ts">import {ref,computed} from 'vue';import type {Workspace} from '../stores/workspace';import {create} from '../api/packages';import {example} from '../utils/example';import {num} from '../utils/format';import {useAction} from '../hooks/useAction';import Heading from '../components/common/Heading.vue';import Notice from '../components/common/Notice.vue';import Empty from '../components/common/Empty.vue';const props=defineProps<{data:Workspace;canWrite:boolean;refresh:()=>Promise<void>}>();const id=ref('demo-package'),text=ref(JSON.stringify(example(),null,2));const pkg=computed(()=>props.data.packages.find(p=>p.id===id.value)||props.data.packages[0]);const{busy,error,notice,act}=useAction();async function save(){const p=await create(JSON.parse(text.value));await props.refresh();id.value=p.id}</script><template><Heading index="02 / TASK DURATIONS" title="三点工期，先核对范围。" detail="单位小时；0≤a≤m≤b，a=m=b为常数。每份新情景冻结完整工作包与工期范围。"/><label class="selector">选择工作包<select aria-label="选择工作包" v-model="id"><option v-for="p in data.packages" :key="p.id" :value="p.id">{{p.name}}</option></select></label><template v-if="pkg"><div class="package-title"><h2>{{pkg.name}}</h2><p>{{pkg.source}} · {{pkg.tasks.length}}任务</p></div><div class="table-scroll"><table><thead><tr><th>任务ID</th><th>工序</th><th>乐观 a / h</th><th>最可能 m / h</th><th>悲观 b / h</th><th>分布</th></tr></thead><tbody><tr v-for="t in pkg.tasks" :key="t.task_id"><td>{{t.task_id}}</td><td>{{t.name}}</td><td>{{num(t.a)}}</td><td>{{num(t.m)}}</td><td>{{num(t.b)}}</td><td>{{t.a===t.b?'点质量 / 常数':'Beta-PERT λ=4'}}</td></tr></tbody></table></div></template><Empty v-else>从下方导入具名任务与三点工期，之后在FS依赖页建立前后关系。</Empty><section v-if="canWrite" class="form-section"><h2>导入新工作包</h2><p>JSON含name、source、tasks；每任务task_id/name/a/m/b，不执行任意公式。</p><form @submit.prevent="act(save,'工作包已校验保存，请继续建立FS依赖')"><label>任务JSON<textarea aria-label="任务JSON" v-model="text" rows="7"/></label><div class="actions"><button class="primary" :disabled="busy">校验并导入工作包</button><button type="button" @click="text=JSON.stringify(example(),null,2)">恢复4任务示例</button></div></form><Notice :error="error" :notice="notice"/></section></template>